function fold(ch: string): string {
  switch (ch) {
    case "\u201c":
    case "\u201d":
    case "\u201e":
    case "\u00ab":
    case "\u00bb":
      return '"';
    case "\u2018":
    case "\u2019":
    case "\u201a":
      return "'";
    case "\u2013":
    case "\u2014":
    case "\u2212":
      return "-";
    case "\u00a0":
    case "\u2009":
    case "\u202f":
      return " ";
