      while (i < source.length && /\s/.test(source[i])) {
        if (source[i] === "\n") breaks++;
        i++;
      }
      if (text.length === 0) continue;
      text += breaks >= 2 ? "\n" : " ";
      map.push(start);
      continue;
    }
    if (ch === "." && source.startsWith("...", i)) {
