export async function runPass(): Promise<PersonaFeedback[]> {
  const blocked = whyNotReady();
  if (blocked) {
    if (blocked !== "already-running") setStatus(enabled ? "idle" : "off");
    return [];
  }

  const draftText = latestText;
  const diff = diffParagraphs(lastReadText, draftText);
  if (diff.added.length === 0) {
    // Words moved but no paragraph is genuinely new — nothing to read.
    state.pendingWords = 0;
    setStatus("idle");
    return [];
  }

  running = true;
  setStatus("reading");
  const folioId = activeFolioId!;
  const token = generation;
  const brief = activeBrief;
  const client = activeClient;
  const personas = [...activePersonas];
  const current = () =>
    generation === token &&
    activeFolioId === folioId &&
    enabled &&
    latestText === draftText;

  try {
    if (
      (await loadMetaFromIdb<boolean>("live-review-enabled")) === false ||
      !current()
    )
      return [];
    // Record the movement before the call, so the digest the editors receive
    // includes the material they are about to read.
    const entry = entryFromDiff(diff);
    const history = entry
      ? await appendTrajectory(folioId, entry)
      : await loadTrajectory(folioId);
    const digest = trajectoryDigest(history);
    let newMaterial = diff.added.join("\n\n");
    const review = liveReviewSnapshot();
    if (
      review.folioId === folioId &&
      review.result &&
      review.status === "current"
    ) {
      const fingerprint = await rubricDraftFingerprint(
        htmlToPlainText(await loadFolioContentFromIdb(folioId)),
      );
      const covered = review.result.passages.filter((item) =>
        diff.added.includes(item.passage.text),
      );
      if (
        current() &&
        fingerprint === review.result.fingerprint &&
        diff.added.every((text) =>
          covered.some((item) => item.passage.text === text),
        )
      ) {
        const selected = selectForAttention(covered, 3);
        if (!selected.length) {
          lastReadText = draftText;
          state.pendingWords = 0;
          setStatus("idle");
          return [];
        }
        newMaterial = selected.map((item) => item.passage.text).join("\n\n");
      }
    }
    if (!current()) return [];

    const responses = await conveneQuietly({
      draftText,
      newMaterial,
      trajectory: digest,
      brief,
      client,
      personas,
    });
    if (!current()) return [];
    if (responses.length === 0) {
      setStatus("idle");
      return [];
    }

    const timestamp = Date.now();
    const notes: PersonaFeedback[] = [];
    const writerProfile = (await loadWriterSettingsFromIdb()).profile;
    for (const r of responses) {
      const persona = personas.find((p) => p.id === r.personaId);
      if (!persona || !r.text.trim()) continue;
      if (client) {
        const verdict = await reviewEditorialNote(
          (request) =>
            askJudgement(client, {
              ...request,
              state: Object.fromEntries(
                Object.entries(request.state).map(([key, value]) => [
                  key,
                  typeof value === "string" ? value : JSON.stringify(value),
                ]),
              ),
            }),
          {
            note: r.text,
            quote: r.anchor,
            draft: draftText,
            brief,
            persona,
            profile: writerProfile,
          },
        );
        if (!current()) return [];
        // Quality uncertainty is left to the writer. A definite source/constraint conflict is withheld.
        if (verdict?.vetoed) continue;
      }
      const note: PersonaFeedback = {
        folioId,
        personaId: r.personaId,
        personaName: persona.name,
        personaColor: persona.color,
        feedback: r.text,
        timestamp,
        type: r.type,
        anchor: r.anchor,
        noteId: `bg-${r.personaId}-${timestamp}`,
        origin: "background",
      };
      notes.push(note);
      if (
        !current() ||
        (await loadMetaFromIdb<boolean>("live-review-enabled")) === false
      )
        return [];
      await savePersonaNoteLocally(note, brief, folioId);
    }

    if (!current()) return [];
    lastReadText = draftText;
    state.pendingWords = 0;
    state.lastPassAt = timestamp;
    state.passesThisSession += 1;
    state.lastNoteCount = notes.length;

    if (typeof window !== "undefined" && notes.length > 0) {
      window.dispatchEvent(
        new CustomEvent("twyne:background-room-notes", { detail: notes }),
      );
    }
    setStatus("idle");
    return notes;
  } catch (err) {
    reportApplicationDiagnostic("twyne:background-room:pass", err, {
      feature: "background-room",
      operation: "pass",
    });
    if (current()) setStatus("error", (err as Error)?.message);
    return [];
  } finally {
    running = false;
  }
}

interface QuietResponse {
  personaId: string;
  text: string;
  type: PersonaFeedback["type"];
  provider: string;
  anchor?: string;
}

/**
 * Run the five editors over the new material. BYOK first, then the server
 * action — the same order the Cast panel uses, so the background room and the
 * explicit convene never disagree about which provider is in play.
 *
 * Returns an empty array rather than throwing when no provider is reachable:
 * a background pass that quietly does nothing is correct, while an error toast
 * the writer never asked for is not.
 */
async function conveneQuietly(input: {
  draftText: string;
  newMaterial: string;
  trajectory: string;
  brief: ProjectBrief | null;
  client: ConvexClient | null;
  personas: Persona[];
}): Promise<QuietResponse[]> {
  const settings = await getCachedAiSettings();
  const writerProfile = (await loadWriterSettingsFromIdb()).profile;

  if (hasConfiguredAiProvider(settings)) {
    const results = await Promise.all(
      input.personas.map(async (p) => {
        const reviewer = input.client
          ? createEditorialNoteReviewer(
              (request) =>
                askJudgement(input.client, {
                  ...request,
                  state: Object.fromEntries(
                    Object.entries(request.state).map(([key, value]) => [
                      key,
                      typeof value === "string" ? value : JSON.stringify(value),
                    ]),
                  ),
                }),
              {
                draft: input.draftText,
                brief: input.brief,
                persona: p,
                profile: writerProfile,
                operation: "feedback",
              },
            )
          : undefined;
        const res = await runClientAgent(
          "persona-feedback",
          {
            persona: toAgentPersona(p),
            brief: input.brief,
            draftText: input.draftText,
            writerProfile,
            newMaterial: input.newMaterial,
            trajectory: input.trajectory,
            instruction: "feedback" as const,
          },
          settings,
          undefined,
          reviewer
            ? {
                review: reviewer,
              }
            : undefined,
        );
        if (!res || !res.text.trim() || res.provider === "local") return null;
        const note: QuietResponse = {
          personaId: p.id,
          text: res.text,
          type: res.type,
          provider: res.provider,
          anchor: res.anchor,
        };
        return note;
      }),
    );
    return results.filter((r): r is QuietResponse => r !== null);
  }

  if (!input.client) return [];
  const result = (await input.client.action(api.agents.conveneRoom, {
    responseLocale: currentModelLocale(),
    personas: input.personas.map(toAgentPersona),
    brief: input.brief ?? null,
    draftText: input.draftText,
    writerProfile,
    newMaterial: input.newMaterial,
    trajectory: input.trajectory,
  })) as QuietResponse[];
  return result.filter((r) => r.text.trim() && r.provider !== "local");
}

/**
 * The trajectory digest for the active folio, for the explicit convene and
 * rubric passes to include. Empty string when there is no history.
 */
export async function currentTrajectoryDigest(): Promise<string> {
  if (!activeFolioId) return "";

