import { falRun, falUpload, pool } from "/home/diogenes/Projects/apps/twyne/launch-videos/_gen/scripts/lib.mjs";
import { MANUAL_NARRATION } from "/home/diogenes/Projects/apps/twyne/src/routes/docs/manual-narration";
const root = "/home/diogenes/Projects/apps/twyne/tmp/manual-narration";
const words = (s: string) => s.toLowerCase().replace(/[^\p{L}\p{N}' ]+/gu, " ").split(/\s+/).filter(Boolean);
const jobs = Object.entries(MANUAL_NARRATION).flatMap(([id, c]) => c.script.map((text, i) => ({ id: `${id}-${i}`, text, file: `${root}/${id}/${i}.wav` })));
const out: string[] = [];
await pool(jobs, 6, async (j) => {
  const url = await falUpload(j.file);
  const r = await falRun("fal-ai/whisper", { audio_url: url, task: "transcribe", language: "en" }, { label: j.id, pollMs: 1500 });
  const heard = words(r.text ?? "");
  const said = words(j.text);
  // word-level LCS ratio
  const m = said.length, n = heard.length;
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let a = 1; a <= m; a++) for (let b = 1; b <= n; b++) dp[a][b] = said[a-1] === heard[b-1] ? dp[a-1][b-1] + 1 : Math.max(dp[a-1][b], dp[a][b-1]);
  const lcs = dp[m][n];
  out.push(`${j.id}\t${(lcs / m).toFixed(2)}\t${(lcs / Math.max(1, n)).toFixed(2)}\t${m}/${n}\t${r.text}`);
});
out.sort();
await Bun.write("/tmp/narration-verify/report.tsv", out.join("\n"));
